    "content": "Reaksiyon Teorisiyle ilgili bağıntılar, Optik model, Doğrudan reaksiyonda tek-adım yaklaşımı, Doğrudan reaksiyonların etkileşim kanalının belirlenmesi, Bileşik çekirdek, Bileşik-çekirdek reaksiyonları.",
