    "content": "Nükleer reaktör kinetiğinin temelleri, çoklu gecikmiş nötron grubu modeli, reaktivite geri besleme mekanizmaları, noktacık kinetiği, çubuk manevraları, kısa ve uzun dönem reaktör tepkileri.",
