    "content": "Parçacık mekaniği, Parçacıklar sisteminin mekaniği, D'Alembert prensibi ve Lagrange denklemleri, hıza bağlı potansiyel ve kayıp fonksiyonu, Varyasyon (Hamilton) prensibi ve Lagrange denklemleri, Varyasyon analizinde bazı teknikler, Holonomik olmayan sistemler için Hamiton prensibi, kütle çekim kuvveti ve Lagrange fonksiyonu, Yörünge denklemi ve Kepler yasaları, Katı cisimlerin bir noktaya göre açısal momentumu ve kinetik enerjisi, Eylemsizlik tensörü ve momenti, Coriolis etkisi, Hamilton fonksiyonu ve Hamilton hareket denklemleri.",
