      "Radon ve radon ölçüm yolları",
      "Gama bozunumu, klasik elektromanyetik ışınımlar ve ışınımların kuantum mekaniği",
      "İleri nükleer reaktör teorisi ıı: kapsam ve temel kavramlar",
