    "content": "İnce filmin tanımı, Kristal yapı, Vakum teknikleri, İnce film elde etme yöntemleri: Fiziksel yöntemler; Buharlaştırma (Elektron Beam, Termal), Sıçratma, Püskütme, Sol-gel, Film kalınlığı belirleme.",
