      "III-V alaşımları: kimyasal bileşim ve temel özellikler",
      "II-VI alaşımları üretim teknikleri: kristal büyütme yöntemleri",
      "III-V alaşımları üretim teknikleri: kristal büyütme ve epitaksi",
      "Kristalografik özellikler: Bravais kafesleri, simetri ve yönelim",
      "Kristal defektleri ve alaşımlardaki etkileri",
      "Ölçüm teknikleri: X-ışını kırınımı (XRD), Raman spektroskopisi",
      "Ölçüm teknikleri: elektron mikroskobu ve optik spektroskopi",
      "II-VI alaşımları uygulamaları: LED, lazer diyot ve fotovoltaik",
      "III-V alaşımları uygulamaları: HEMT, fotodetektörler, güneş pilleri",
      "Elektronik ve optoelektronik özelliklerin karşılaştırılması",
      "Güncel araştırmalar ve endüstriyel uygulamalar",
      "Genel gözden geçirme",
      "Bileşik yarıiletkenler: kapsam ve temel kavramlar"
